fn register_group(g: &GroupReg) {
    match g.kind {
        RegKind::IterTable {
            min_col,
            max_col,
            row_count,
            handler,
        } => {
            agentx::register_iter_table(
                g.name,
                g.root,
                agentx::ASN_INTEGER,
                min_col,
                max_col,
                row_count,
                handler,
            );
        }
        RegKind::Subtree => {
            agentx::register_handler(
                g.name,
                g.root,
                agentx::HANDLER_CAN_RWRITE,
                moxa_config_handler,
            );
        }
    }
}

